look.customCSS:
/* ───── 星空 · 第一批：夜空、月亮、顶栏月相、气泡、头像光环、底栏 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/240px 240px,radial-gradient(ellipse at 15% 35%,rgba(63,208,201,.09),transparent 55%),radial-gradient(ellipse at 90% 55%,rgba(230,107,208,.09),transparent 55%),linear-gradient(180deg,#05061A 0%,#0A0B26 40%,#1A1440 65%,#3A2468 85%,#8A4278 95%,#D98670 100%) !important;position:relative !important}
/* 大月亮和山：钉在底下，不跟着消息滚，消息从它上面滑过 */
[data-wk="chat"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:0 !important;height:56% !important;background:url("data:image/svg+xml;base64,") center bottom/cover no-repeat !important;pointer-events:none !important;z-index:0 !important;opacity:.95 !important}
[data-wk="body"]{background:transparent !important;position:relative !important;z-index:1 !important}
/* 顶栏：深夜色半透明，底下一排月相，今天那颗亮 */
[data-wk="chathead"]{background:rgba(7,10,34,.72) !important;border-bottom:none !important;box-shadow:none !important;position:relative !important;z-index:5 !important;overflow:visible !important;backdrop-filter:blur(6px) !important;-webkit-backdrop-filter:blur(6px) !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:calc(100% - 12px) !important;height:24px !important;background:center/auto 24px no-repeat !important;pointer-events:none !important}
html[data-lisa-moon="0"] [data-wk="chathead"]::after{background-image:url("data:image/svg+xml;base64,") !important}
html[data-lisa-moon="1"] [data-wk="chathead"]::after{background-image:url("data:image/svg+xml;base64,") !important}
html[data-lisa-moon="2"] [data-wk="chathead"]::after{background-image:url("data:image/svg+xml;base64,") !important}
html[data-lisa-moon="3"] [data-wk="chathead"]::after{background-image:url("data:image/svg+xml;base64,") !important}
html[data-lisa-moon="4"] [data-wk="chathead"]::after{background-image:url("data:image/svg+xml;base64,") !important}
html[data-lisa-moon="5"] [data-wk="chathead"]::after{background-image:url("data:image/svg+xml;base64,") !important}
html[data-lisa-moon="6"] [data-wk="chathead"]::after{background-image:url("data:image/svg+xml;base64,") !important}
html[data-lisa-moon="7"] [data-wk="chathead"]::after{background-image:url("data:image/svg+xml;base64,") !important}
[data-wk="headink"]{color:#F4F1FF !important}
[data-wk="headdim"]{color:#B4B0E0 !important}
[data-wk="chatback"] svg{stroke:#F4F1FF !important}
[data-wk="chatmore"],[data-wk="sameroom"]{border:none !important;box-shadow:none !important;background:url("data:image/svg+xml;base64,") center/40px auto no-repeat !important;width:44px !important}
[data-wk="sameroom"]{background-image:url("data:image/svg+xml;base64,") !important;background-size:36px 36px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="body"]{padding-top:22px !important}

/* 头像：金色刻度光环 */
[data-wk="avatar"]{position:relative !important;overflow:visible !important;border-radius:50% !important}
[data-wk="avatar"] *{border-radius:50% !important}
img[data-wk="avatar"],[data-wk="avatar"] img{clip-path:circle(50%) !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;inset:-38% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important;z-index:2 !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]){position:relative !important;overflow:visible !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"])::before{content:"" !important;position:absolute !important;width:62px !important;height:62px !important;left:-13px !important;top:calc(50% - 31px) !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important;z-index:2 !important}

/* 气泡：你的紫色渐变带星点，他的磨砂玻璃金边；角上闪一颗四角星 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;color:#F4F1FF !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:url("data:image/svg+xml;base64,") 0 0/120px 120px,linear-gradient(135deg,#6F5BFF,#C56BE0) !important;border-radius:22px 4px 22px 22px !important;box-shadow:0 0 0 3px rgba(181,140,255,.18) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(180deg,rgba(255,255,255,.2),rgba(255,255,255,.05)),rgba(11,15,43,.45) !important;backdrop-filter:blur(4px) !important;-webkit-backdrop-filter:blur(4px) !important;border-radius:4px 22px 22px 22px !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;top:-10px !important;width:22px !important;height:22px !important;border:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:none !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{left:-10px !important;right:auto !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{right:-12px !important;left:auto !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
/* 已读：前面一颗月亮，送达是半月、已读是满月 */
[data-wk="meta"]{color:#B4B0E0 !important}
[data-wk="meta"]::before{content:"" !important;display:inline-block !important;width:11px !important;height:11px !important;margin-right:4px !important;vertical-align:-1px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy03IC03IDE0IDE0Jz48Zz48Y2lyY2xlIHI9JzUuNScgZmlsbD0nIzBCMEYyQicgZmlsbC1vcGFjaXR5PScuNicgc3Ryb2tlPScjRkZEOThBJyBzdHJva2Utd2lkdGg9Jy45Jy8+PGNpcmNsZSByPSc1LjUnIGZpbGw9JyNGRkQ5OEEnLz48L2c+PC9zdmc+") center/contain no-repeat !important}
[data-wk="meta"][data-me="1"]::before{background-image:url("data:image/svg+xml;base64,") !important}
/* 时间：两道渐隐金线夹着，两头各一颗星 */
[data-wk="time"] > span{color:#FFD98A !important;letter-spacing:.15em !important;padding:0 26px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy0xMCAtMTAgMjAgMjAnPjxwYXRoIGQ9J00wIC05IFExLjA4IC0xLjA4IDkgMCBRMS4wOCAxLjA4IDAgOSBRLTEuMDggMS4wOCAtOSAwIFEtMS4wOCAtMS4wOCAwIC05WicgZmlsbD0nI0ZGRDk4QScvPjwvc3ZnPg==") left center/10px 10px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy0xMCAtMTAgMjAgMjAnPjxwYXRoIGQ9J00wIC05IFExLjA4IC0xLjA4IDkgMCBRMS4wOCAxLjA4IDAgOSBRLTEuMDggMS4wOCAtOSAwIFEtMS4wOCAtMS4wOCAwIC05WicgZmlsbD0nI0ZGRDk4QScvPjwvc3ZnPg==") right center/10px 10px no-repeat !important;position:relative !important}
[data-wk="time"]{background:linear-gradient(90deg,transparent 10%,rgba(255,217,138,.6) 35%,transparent 35%,transparent 65%,rgba(255,217,138,.6) 65%,transparent 90%) center/100% 1px no-repeat !important}

/* 底栏：金边玻璃胶囊，发送是一颗小月亮 */
[data-wk="composer"]{background:transparent !important;border-top:none !important;position:relative !important;z-index:2 !important}
[data-wk="composer"] > div:has([data-wk="chatinput"]),[data-wk="chatinput"]{background:transparent !important}
[data-wk="chatinput"]{color:#F4F1FF !important;border:none !important;border-radius:0 !important;background:transparent !important;box-shadow:none !important}
/* 整个底栏画成一颗金边玻璃胶囊，加号、输入框、发送、回复都包在里面 */
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:8px !important;right:8px !important;top:6px !important;bottom:calc(env(safe-area-inset-bottom) * .4 + 6px) !important;border-radius:999px !important;border:1.3px solid rgba(255,217,138,.8) !important;background:linear-gradient(180deg,rgba(255,255,255,.18),rgba(255,255,255,.04)),rgba(7,10,34,.62) !important;backdrop-filter:blur(6px) !important;-webkit-backdrop-filter:blur(6px) !important;pointer-events:none !important;z-index:0 !important}
[data-wk="composer"] > *{position:relative !important;z-index:1 !important}
[data-wk="composer"] > div{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="chatinput"]::placeholder{color:#B4B0E0 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;transition:transform .12s !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatreply"]{background:url("data:image/svg+xml;base64,") center/78% no-repeat !important;margin-right:6px !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.86) !important}

/* 底栏四颗键一样大、上下居中 */
[data-wk="composer"]{align-items:center !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{width:38px !important;height:38px !important;min-width:38px !important;align-self:center !important;margin-top:0 !important;margin-bottom:0 !important;transform:none !important;background-size:contain !important}
[data-wk="send"]{background-size:120% !important}
/* 月亮调暗，压在字后面不抢眼 */
[data-wk="chat"]::before{opacity:.72 !important;filter:brightness(.9) !important}
/* 流星：每隔几秒从右上划过一颗 */
@keyframes snMeteor{0%{transform:translate(0,0) rotate(-32deg);opacity:0}3%{opacity:1}14%{transform:translate(-420px,260px) rotate(-32deg);opacity:0}100%{transform:translate(-420px,260px) rotate(-32deg);opacity:0}}
@keyframes snMeteor2{0%,40%{transform:translate(0,0) rotate(-28deg);opacity:0}43%{opacity:.9}54%{transform:translate(-380px,220px) rotate(-28deg);opacity:0}100%{opacity:0}}
[data-wk="chat"]::after{content:"" !important;position:absolute !important;top:120px !important;right:-140px !important;width:130px !important;height:3px !important;border-radius:3px !important;background:linear-gradient(90deg,#fff,rgba(255,217,138,.7) 30%,transparent) !important;box-shadow:0 0 8px 1px rgba(255,255,255,.6) !important;pointer-events:none !important;z-index:0 !important;animation:snMeteor 4s ease-in infinite !important}
[data-wk="body"]::before{content:"" !important;position:fixed !important;top:300px !important;right:-100px !important;width:90px !important;height:2px !important;border-radius:2px !important;background:linear-gradient(90deg,#fff,rgba(168,240,255,.6) 30%,transparent) !important;pointer-events:none !important;animation:snMeteor2 5.5s ease-in infinite !important}
@media (prefers-reduced-motion:reduce){[data-wk="chat"]::after,[data-wk="body"]::before{animation:none !important;opacity:0 !important}}
/* 系统提示：一行星座连线小字，不要白框 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important;text-align:center !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{color:#B4B0E0 !important;font-style:normal !important;font-size:12px !important;letter-spacing:.06em !important}
[data-wk="sysnotetext"]::before{content:"✦ " !important;color:#FFD98A !important}
[data-wk="sysnoteclose"]{color:#B4B0E0 !important;opacity:.6 !important}
[data-wk="narrink"]{color:#B4B0E0 !important}
[data-wk="name"]{color:#B4B0E0 !important}

/* 第三颗流星 */
@keyframes snMeteor3{0%,60%{transform:translate(0,0) rotate(-36deg);opacity:0}62%{opacity:1}74%{transform:translate(-460px,300px) rotate(-36deg);opacity:0}100%{opacity:0}}
[data-wk="body"]::after{content:"" !important;position:fixed !important;top:180px !important;left:105% !important;width:110px !important;height:2.5px !important;border-radius:2px !important;background:linear-gradient(90deg,#fff,rgba(245,184,255,.6) 30%,transparent) !important;box-shadow:0 0 6px rgba(255,255,255,.5) !important;pointer-events:none !important;animation:snMeteor3 8s ease-in infinite !important}
@media (prefers-reduced-motion:reduce){[data-wk="body"]::after{animation:none !important;opacity:0 !important}}

/* ───── 第二批：卡片都是磨砂玻璃＋金边，像夜空里的一块星图 ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="voice"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{background:linear-gradient(180deg,rgba(255,255,255,.18),rgba(255,255,255,.05)),rgba(11,15,43,.55) !important;border:1.2px solid rgba(255,217,138,.75) !important;backdrop-filter:blur(5px) !important;-webkit-backdrop-filter:blur(5px) !important;color:#F4F1FF !important;border-radius:18px !important;box-shadow:0 0 18px rgba(255,217,138,.12) !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *{color:#F4F1FF !important;border-color:rgba(255,217,138,.35) !important}
/* 转账：金额是金色，已收是一颗满月章，待收是新月章 */
[data-wk="transferamount"],[data-wk="transfercur"]{color:#FFD98A !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:linear-gradient(90deg,transparent,rgba(255,217,138,.7),transparent) !important}
[data-wk="transfernotch"]{background:#1B1A52 !important}
[data-wk="transferfoot"]{background:rgba(255,255,255,.06) !important}
[data-wk="transferseal"]{width:52px !important;height:52px !important;border:none !important;box-shadow:none !important;border-radius:50% !important;color:#0B0F2B !important;font-weight:700 !important;background:radial-gradient(circle at 38% 35%,#FFFBEA,#FFE3A3 60%,#E9B25A) !important;opacity:1 !important}
[data-wk="transferseal"] *{color:#0B0F2B !important}
[data-wk="transfercard"][data-status="pending"] [data-wk="transferseal"]{background:rgba(11,15,43,.6) !important;border:1.5px solid #FFD98A !important;color:#FFD98A !important}
[data-wk="transfercard"][data-status="pending"] [data-wk="transferseal"] *{color:#FFD98A !important}
[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"]{background:rgba(180,176,224,.25) !important;color:#B4B0E0 !important}
[data-wk="transferbtn"]{border-radius:999px !important}
[data-wk="transferbtn"][data-part="take"]{background:linear-gradient(135deg,#6F5BFF,#C56BE0) !important;color:#fff !important;border:none !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;color:#B4B0E0 !important;border:1px solid rgba(180,176,224,.5) !important}
/* 红包：留红，像一盏小灯笼，扣子是金色满月 */
[data-wk="rpcard"]{border-radius:18px !important;box-shadow:0 0 22px rgba(255,217,138,.2) !important;border:1.2px solid rgba(255,217,138,.7) !important}
[data-wk="rpseal"]{border:none !important;background:radial-gradient(circle at 38% 35%,#FFFBEA,#FFE3A3 60%,#E9B25A) !important;box-shadow:0 0 10px rgba(255,217,138,.7) !important}
[data-wk="rpseal"] *{display:none !important}
[data-wk="rpenvelope"][data-stage="open"]{background:linear-gradient(180deg,#1B1A52,#4A2A78) !important;border:1.2px solid rgba(255,217,138,.7) !important}
[data-wk="rpenvelope"][data-stage="open"] *{color:#F4F1FF !important}
[data-wk="rpamount"]{color:#FFD98A !important}
[data-wk="rpopenbtn"]{background:radial-gradient(circle at 38% 35%,#FFFBEA,#FFE3A3 60%,#E9B25A) !important;box-shadow:0 0 18px rgba(255,217,138,.8) !important}
/* 照片：没图时是一块望远镜里的圆形星空 */
[data-wk="photoface"]{background:radial-gradient(circle,rgba(108,123,255,.35),rgba(7,10,34,.9) 70%),#070A22 !important;border:1px solid rgba(255,217,138,.5) !important;border-radius:14px !important}
[data-wk="phototext"],[data-wk="photocap"],[data-wk="photohint"]{color:#F4F1FF !important}
/* 语音、天气、位置、名片 */
[data-wk="voice"] > *{background:transparent !important;box-shadow:none !important;border:none !important;color:#F4F1FF !important}
[data-wk="voice"] [data-wk="voicebar"]{background:transparent !important}
[data-wk="voicewave"] span{background:#FFD98A !important}
[data-wk="wxcardsky"]{background:linear-gradient(170deg,rgba(108,123,255,.35),rgba(74,42,120,.5)) !important;color:#F4F1FF !important}
[data-wk="wxcardsky"] *{color:#F4F1FF !important}
[data-wk="wxcardsky"] svg{stroke:#FFD98A !important}
[data-wk="wxcardsay"]{background:transparent !important;color:#F4F1FF !important;border-top:1px solid rgba(255,217,138,.35) !important}
[data-wk="geopin"]{background:#FFD98A !important;box-shadow:0 0 10px #FFD98A !important}
[data-wk="geopinstem"]{background:#FFD98A !important}
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 2px #FFD98A !important}
/* 拍一拍、通话结束、线下小结 */
[data-wk="note"]{color:#B4B0E0 !important}
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{background:rgba(11,15,43,.5) !important;border:1px solid rgba(255,217,138,.55) !important;border-radius:999px !important;color:#FFD98A !important;padding:2px 14px !important}
[data-wk="note"][data-part="call"] svg{stroke:#FFD98A !important}
[data-wk="offlogtitle"]{color:#FFD98A !important;letter-spacing:.2em !important}
/* 加号面板：一片夜空里的金边圆星球 */
[data-wk="chatpanel"]{background:linear-gradient(180deg,rgba(7,10,34,.9),rgba(27,26,82,.95)) !important;border-top:1px solid rgba(255,217,138,.5) !important}
[data-wk="chattoolicon"]{background:radial-gradient(circle at 35% 30%,rgba(255,255,255,.18),rgba(11,15,43,.6)) !important;border:1.2px solid rgba(255,217,138,.75) !important;border-radius:50% !important;box-shadow:0 0 12px rgba(255,217,138,.18) !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#FFD98A !important;color:#FFD98A !important}
[data-wk="chattoollabel"]{color:#B4B0E0 !important}
/* 引用、正在输入 */
[data-wk="quotedraft"]{background:rgba(11,15,43,.7) !important;border-left:2px solid #FFD98A !important}
[data-wk="quotedraft"] *{background:transparent !important;color:#B4B0E0 !important;border:none !important}
[data-wk="bubble"][data-kind="typing"]{background:rgba(11,15,43,.45) !important;border:1.2px solid rgba(255,217,138,.6) !important}
[data-wk="bubble"][data-kind="typing"]::before{content:none !important}
[data-wk="typingdot"]{width:10px !important;height:10px !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy0xMCAtMTAgMjAgMjAnPjxwYXRoIGQ9J00wIC05IFExLjA4IC0xLjA4IDkgMCBRMS4wOCAxLjA4IDAgOSBRLTEuMDggMS4wOCAtOSAwIFEtMS4wOCAtMS4wOCAwIC05WicgZmlsbD0nI0ZGRDk4QScvPjwvc3ZnPg==") center/contain no-repeat !important;animation-duration:1.2s !important}

/* 系统字、动描压在月亮上也看得清：垫一层夜色小底 */
[data-wk="sysnotetext"],[data-wk="narrink"],[data-wk="name"]{background:rgba(7,10,34,.62) !important;border-radius:12px !important;padding:2px 10px !important;-webkit-box-decoration-break:clone !important;box-decoration-break:clone !important;text-shadow:0 1px 2px rgba(0,0,0,.6) !important}
[data-wk="sysnotetext"],[data-wk="narrink"]{display:inline !important;line-height:2 !important;color:#E4E0FF !important}
[data-wk="meta"]{text-shadow:0 1px 2px rgba(0,0,0,.7) !important}

/* 胶囊放大，按键缩一点，全包进去 */
[data-wk="composer"]::before{left:6px !important;right:6px !important;top:2px !important;bottom:calc(env(safe-area-inset-bottom) * .4 + var(--composer-lift, 0px) - 8px) !important}
[data-wk="composer"]{padding-left:16px !important;padding-right:16px !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{width:34px !important;height:34px !important;min-width:34px !important;margin:0 !important}
[data-wk="chatreply"]{background-size:100% !important}
[data-wk="send"]{background-size:118% !important;opacity:1 !important}

/* 头像框：月牙抱着头像；我的那颗左右翻过来 */
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{inset:-30% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
span[data-wk="avatar"]:not([data-halo])::before{transform:scaleX(-1) !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"])::before{width:58px !important;height:58px !important;left:-11px !important;top:calc(50% - 29px) !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}

