[data-wk="rpenvelope"][data-stage="open"] [data-wk="rpamount"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy0xMCAtMTAgMjAgMjAnPjxwYXRoIGQ9J00wIC0xMCBRMS4yIC0xLjIgMTAgMCBRMS4yIDEuMiAwIDEwIFEtMS4yIDEuMiAtMTAgMCBRLTEuMiAtMS4yIDAgLTEwWicgZmlsbD0ncmdiYSgyNTUsMjE3LDEzOCwuMjIpJy8+PC9zdmc+") center/110px 110px no-repeat !important;padding:30px 30px !important}

/* ───── 转账＝星际船票 ───── */
[data-wk="transfercard"]{background:radial-gradient(circle at 0 62%,#05061A 9px,transparent 10px),radial-gradient(circle at 100% 62%,#05061A 9px,transparent 10px),linear-gradient(135deg,#1B1A52,#0B0F2B 70%) !important;border:1.2px solid rgba(255,217,138,.7) !important;border-radius:12px !important;padding-top:28px !important;position:relative !important}
[data-wk="transfercard"]::before{content:"✦ STAR EXPRESS · 单程 地球 → 月亮" !important;position:absolute !important;left:16px !important;top:9px !important;font-size:9.5px !important;letter-spacing:.14em !important;color:#FFD98A !important;opacity:.85 !important}
[data-wk="transfercard"]::after{content:"" !important;position:absolute !important;right:14px !important;top:30px !important;width:26px !important;height:50px !important;background:repeating-linear-gradient(90deg,rgba(255,217,138,.55) 0 1px,transparent 1px 3px,rgba(255,217,138,.55) 3px 5px,transparent 5px 8px) !important;opacity:.6 !important}
[data-wk="transferlabel"]::after{content:" · 票价" !important;color:#B4B0E0 !important}
[data-wk="transferrule"]{background:repeating-linear-gradient(90deg,rgba(255,217,138,.7) 0 4px,transparent 4px 8px) !important;height:1px !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transfernote"]::before{content:"乘客留言：" !important;color:#B4B0E0 !important;font-size:.85em !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{transform:rotate(-14deg) !important;box-shadow:0 0 0 2px rgba(11,15,43,.8),0 0 0 3.5px #FFD98A !important}
[data-wk="transfercard"][data-status="returned"]{clip-path:polygon(0 0,calc(100% - 26px) 0,100% 26px,100% 100%,0 100%) !important;opacity:.75 !important}

/* ───── 红包＝一封星光信封（照她给的图） ───── */
[data-wk="rpcard"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;width:62px !important;height:46px !important;margin-top:-23px !important;animation:none !important;filter:drop-shadow(0 0 6px rgba(227,196,135,.35)) !important}
[data-wk="rpcard"]::after{content:"一份星光" !important}
/* 拆开前 */
[data-wk="rpenvelope"][data-stage="closed"]{background:radial-gradient(circle at 50% 60%,rgba(227,196,135,.14),transparent 38%),url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAzMDAgNDcwJyBwcmVzZXJ2ZUFzcGVjdFJhdGlvPSdub25lJz48cmVjdCB4PScxNCcgeT0nMTQnIHdpZHRoPScyNzInIGhlaWdodD0nNDQyJyByeD0nMjInIGZpbGw9J25vbmUnIHN0cm9rZT0nI0UzQzQ4Nycgc3Ryb2tlLXdpZHRoPScxLjQnIG9wYWNpdHk9Jy44NScvPjwvc3ZnPg==") center/100% 100% no-repeat,url("data:image/svg+xml;base64,") center/100% 100% no-repeat,#12112E !important;border:none !important;box-shadow:0 20px 50px rgba(0,0,0,.5) !important}
[data-wk="rpenvelope"][data-stage="closed"] [data-wk="rpavatar"]{visibility:hidden !important}
