[data-wk="rpenvelope"][data-stage="closed"] [data-wk="rpwish"]{color:#FFF4DC !important;font-weight:700 !important;font-size:24px !important}
[data-wk="rpopenbtn"]{background:#E3C487 url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9Jy0xMiAtMTIgMjQgMjQnPjxwYXRoIGQ9J00wIC05IFEuOSAtLjkgOSAwIFEuOSAuOSAwIDkgUS0uOSAuOSAtOSAwIFEtLjkgLS45IDAgLTlaJyBmaWxsPScjM0EyRTY2Jy8+PC9zdmc+") center/58% no-repeat !important;width:54px !important;height:54px !important;margin-left:-27px !important;margin-top:-27px !important;top:66.5% !important;border-radius:50% !important;filter:none !important;animation:snPulse 2s ease-in-out infinite !important;box-shadow:0 0 18px rgba(227,196,135,.5) !important}
[data-wk="chatmore"]{font-size:0 !important;color:transparent !important;width:44px !important;min-width:44px !important;height:30px !important;min-height:30px !important;display:inline-block !important;flex:none !important}

/* 引用：一颗流星拖着尾巴划向那句话 */
[data-wk="quotedraft"]{background:linear-gradient(90deg,rgba(255,217,138,.16),rgba(11,15,43,.75) 45%) !important;border:1px solid rgba(255,217,138,.45) !important;border-left:none !important;border-radius:0 18px 18px 0 !important;position:relative !important;padding-left:58px !important;overflow:visible !important}
[data-wk="quotedraft"]::before{content:"" !important;position:absolute !important;left:6px !important;top:50% !important;width:48px !important;height:20px !important;margin-top:-10px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 4px #FFD98A) !important}
[data-wk="quoteicon"]{display:none !important}
[data-wk="quotetext"]{color:#E4E0FF !important;font-style:italic !important}
[data-wk="quoteclear"]{color:#FFD98A !important}
/* 气泡里被引用的那句：上面一道细金线＋小星 */
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:2px solid rgba(255,217,138,.7) !important;padding-left:8px !important;opacity:.85 !important}

/* 气泡上面那条「回复了哪句」：深色玻璃＋金色细边，字看得清 */
[data-wk="quote"]{background:rgba(8,9,30,.78) !important;color:#E4E0FF !important;border:1px solid rgba(255,217,138,.5) !important;border-left:2px solid #FFD98A !important;border-radius:10px !important;padding:3px 10px !important;font-style:italic !important;opacity:1 !important}
[data-wk="quote"]::before{content:"✦ " !important;color:#FFD98A !important;font-style:normal !important}

/* 线下小结＝一页观星日志：顶上一排月相小标、金色标题，按键是小金胶囊 */
[data-part="offlog"]{background:url("data:image/svg+xml;base64,") 0 0/240px 240px,linear-gradient(180deg,rgba(8,9,30,.92),rgba(26,20,64,.9)) !important;border:1px solid rgba(255,217,138,.6) !important;border-radius:20px !important;padding:16px 18px 14px !important;position:relative !important}
[data-wk="offlogtitle"]{display:flex !important;align-items:center !important;gap:8px !important;font-size:12px !important;letter-spacing:.3em !important;color:#FFD98A !important;padding-bottom:8px !important;margin-bottom:8px !important;border-bottom:1px solid rgba(255,217,138,.3) !important}
[data-wk="offlogtitle"]::before{content:"" !important;width:16px !important;height:16px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="offlogtitle"]::after{content:"观星日志" !important;margin-left:auto !important;font-size:9px !important;letter-spacing:.2em !important;color:#B4B0E0 !important;opacity:.7 !important}
[data-wk="offlogtext"],[data-wk="offlogtext"] *{color:#F4F1FF !important;line-height:1.8 !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{display:inline-block !important;margin:8px 6px 0 0 !important;padding:3px 12px !important;border:1px solid rgba(255,217,138,.55) !important;border-radius:999px !important;color:#FFD98A !important;font-size:11px !important;background:rgba(11,15,43,.5) !important}
[data-wk="offlogtranscript"]{border-top:1px solid rgba(255,217,138,.3) !important;color:#B4B0E0 !important}

/* 打电话那一屏（语音）：整屏底色跟这套走；三个按键换成这套的扣子，中间挂断单独一色 */
[data-wk="call"][data-video="0"]{background:radial-gradient(circle at 70% 15%,rgba(255,217,138,.3),transparent 40%),linear-gradient(180deg,#070A22,#1B1A52 50%,#4A2A78) !important}
[data-wk="call"][data-video="0"] [data-wk="calltitle"]{color:#fff !important}
[data-wk="call"][data-video="0"] [data-wk="callhead"] > div:not([data-wk]){color:rgba(255,255,255,.65) !important}
[data-wk="call"][data-video="0"] > button:first-child{background:rgba(255,255,255,.12) !important}
[data-wk="call"][data-video="0"] > button:first-child svg{stroke:#fff !important}
[data-wk="callbtns"] button > span:first-child{background:rgba(11,15,43,.55) !important;border-radius:50% !important;box-shadow:0 0 0 1.5px #FFD98A,0 0 16px rgba(255,217,138,.45) !important}
[data-wk="callbtns"] button > span:first-child svg{stroke:#FFD98A !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child{background:#A2477F !important;box-shadow:0 0 0 1.5px #FFD98A,0 0 16px rgba(240,154,120,.5) !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child svg{stroke:#fff !important}
[data-wk="call"][data-video="0"] [data-wk="callbtns"] button > span:last-child{color:rgba(255,255,255,.65) !important}
